window.DRILLS = {"L1": {"video": "drill_l1", "title": "First Read", "tag": "BASELINE", "nar": ["Now take one clean read of how you react, before you learn the rest of the system. This drill is short.", "Press Play. Melissa will pause partway through and ask what you notice. Type your answer, and the video will resume."], "beats": [{"t": 11.9, "u": 27.5, "kind": "shift", "text": "Something you were counting on just fell through."}, {"t": 17.2, "u": 28.2, "kind": "notice", "text": "What do you notice first? In your body, your thoughts, the urge to act."}, {"t": 34.3, "u": 50.5, "kind": "reframe", "text": "There's no right answer. What you noticed is data: the signal your system sends before you decide anything."}, {"t": 51.0, "u": 65.6, "kind": "condition", "text": "Every time something falls through this season, catch that signal before you act on it."}], "holds": [{"t": 28.25, "resume": 33.9, "key": "notice", "kind": "text", "label": "NOTICE", "q": "What's the first thing you notice? In your body, in your thoughts, the urge to do something."}]}};
